-- Relay is a single-owner server application. Nothing here is exposed through the Data API.
-- Text IDs, source JSON and ISO timestamp strings preserve the SQLite evidence byte-for-byte.
CREATE SCHEMA relay;
REVOKE ALL ON SCHEMA relay FROM PUBLIC;
CREATE ROLE relay_backend NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT relay_backend TO CURRENT_USER;
GRANT USAGE ON SCHEMA relay TO relay_backend;

CREATE TABLE relay.schema_migrations(version integer PRIMARY KEY, contract text NOT NULL);
CREATE TABLE relay.workspace_state(id text PRIMARY KEY CHECK(id='default'), key_digest text NOT NULL, import_digest text, imported_at text NOT NULL);
CREATE TABLE relay.destinations(id text PRIMARY KEY,name text NOT NULL,url text NOT NULL,status text NOT NULL CHECK(status IN ('active','paused')),daily_cap bigint NOT NULL CHECK(daily_cap>=0),created_at text NOT NULL);
CREATE TABLE relay.campaigns(id text PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,source text NOT NULL,status text NOT NULL CHECK(status IN ('active','paused')),cost_cents bigint NOT NULL,fallback_id text REFERENCES relay.destinations(id),rules text NOT NULL,postback_token text NOT NULL,created_at text NOT NULL,crawler_routing text NOT NULL);
CREATE TABLE relay.clicks(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES relay.campaigns(id),destination_id text NOT NULL REFERENCES relay.destinations(id),rule_name text NOT NULL,visitor_hash text NOT NULL,device text NOT NULL,source text NOT NULL,external_id text NOT NULL,cost_cents bigint NOT NULL,created_at text NOT NULL);
CREATE INDEX clicks_campaign_date ON relay.clicks(campaign_id,created_at);
CREATE INDEX clicks_destination_date ON relay.clicks(destination_id,created_at);
CREATE TABLE relay.conversions(id text PRIMARY KEY,click_id text NOT NULL REFERENCES relay.clicks(id),campaign_id text NOT NULL REFERENCES relay.campaigns(id),transaction_id text NOT NULL,revenue_cents bigint NOT NULL,status text NOT NULL CHECK(status IN ('approved','rejected')),created_at text NOT NULL,UNIQUE(campaign_id,transaction_id));
CREATE INDEX conversions_campaign_date ON relay.conversions(campaign_id,created_at);
CREATE TABLE relay.articles(id text PRIMARY KEY,title text NOT NULL,slug text NOT NULL UNIQUE,excerpt text NOT NULL,body text NOT NULL,status text NOT NULL CHECK(status IN ('draft','published')),campaign_id text REFERENCES relay.campaigns(id),cta text NOT NULL,origin text NOT NULL,created_at text NOT NULL,updated_at text NOT NULL,published_at text);
CREATE TABLE relay.settings(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE relay.crawler_requests(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES relay.campaigns(id),provider text NOT NULL CHECK(provider IN ('google','meta')),user_agent text NOT NULL,destination_url text NOT NULL,source text NOT NULL,created_at text NOT NULL,identity text);
CREATE INDEX crawler_requests_campaign_date ON relay.crawler_requests(campaign_id,created_at);
CREATE TABLE relay.traffic_policies(id text PRIMARY KEY,policy text NOT NULL);
CREATE TABLE relay.traffic_config_history(sequence bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,policy_id text NOT NULL REFERENCES relay.traffic_policies(id),changed_at text NOT NULL,raw_config text NOT NULL);
CREATE TABLE relay.traffic_requests(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES relay.campaigns(id),click_id text REFERENCES relay.clicks(id),source text NOT NULL,external_id text NOT NULL,created_at text NOT NULL,context text NOT NULL,destination_url text,actual_action text NOT NULL,mode text NOT NULL,cost_cents bigint NOT NULL,collection text NOT NULL,session_key text NOT NULL,policy_id text NOT NULL REFERENCES relay.traffic_policies(id),rate_count bigint);
CREATE INDEX traffic_request_date ON relay.traffic_requests(created_at DESC,id);
CREATE INDEX traffic_request_campaign ON relay.traffic_requests(campaign_id,created_at DESC);
CREATE TABLE relay.traffic_assessments(sequence bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id text NOT NULL REFERENCES relay.traffic_requests(id) ON DELETE CASCADE,created_at text NOT NULL,assessment text NOT NULL);
CREATE INDEX traffic_assessment_request ON relay.traffic_assessments(request_id,sequence DESC);
CREATE TABLE relay.traffic_observations(id text PRIMARY KEY,request_id text NOT NULL REFERENCES relay.traffic_requests(id) ON DELETE CASCADE,kind text NOT NULL,created_at text NOT NULL,schema_version integer NOT NULL,facts text NOT NULL);
CREATE TABLE relay.telemetry_sessions(request_id text PRIMARY KEY REFERENCES relay.traffic_requests(id) ON DELETE CASCADE,token_hash text NOT NULL,origin text NOT NULL,expires_at text NOT NULL,completed_at text,payload_hash text);
CREATE TABLE relay.intelligence_revisions(revision text PRIMARY KEY,service text NOT NULL,source text NOT NULL,fetched_at text NOT NULL,expires_at text NOT NULL,ranges text NOT NULL);
CREATE INDEX intelligence_service ON relay.intelligence_revisions(service,fetched_at DESC);
-- SQLite's label rowid was used for last-label selection; preserve it as an explicit sequence.
CREATE TABLE relay.traffic_labels(id text PRIMARY KEY,request_id text NOT NULL REFERENCES relay.traffic_requests(id) ON DELETE CASCADE,label text NOT NULL,provenance text NOT NULL,created_at text NOT NULL,sequence bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE NOT NULL);
CREATE INDEX traffic_label_request ON relay.traffic_labels(request_id,sequence DESC);
CREATE TABLE relay.traffic_challenges(token_hash text PRIMARY KEY,request_id text NOT NULL REFERENCES relay.traffic_requests(id) ON DELETE CASCADE,expires_at text NOT NULL,completed_at text);
CREATE TABLE relay.traffic_actions(id text PRIMARY KEY,request_id text NOT NULL REFERENCES relay.traffic_requests(id) ON DELETE CASCADE,action text NOT NULL,created_at text NOT NULL,reason text NOT NULL);

DO $migration$
DECLARE item record;
BEGIN
  FOR item IN SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='relay' LOOP
    EXECUTE format('ALTER TABLE relay.%I ENABLE ROW LEVEL SECURITY', item.tablename);
    EXECUTE format('REVOKE ALL ON relay.%I FROM PUBLIC', item.tablename);
    EXECUTE format('CREATE POLICY backend_access ON relay.%I TO relay_backend USING (true) WITH CHECK (true)', item.tablename);
    IF item.tablename IN ('schema_migrations','workspace_state') THEN
      EXECUTE format('GRANT SELECT ON relay.%I TO relay_backend', item.tablename);
    ELSE
      EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON relay.%I TO relay_backend', item.tablename);
    END IF;
  END LOOP;
END
$migration$;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA relay TO relay_backend;
INSERT INTO relay.schema_migrations VALUES(1,'relay-postgres-v1');
